import{_ as t,o,c as a,ae as r}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Helper vs Util","description":"","frontmatter":{"id":"1146361044","title":"Helper vs Util","state":"Approved","created":"2022-07-11T00:00:00.000Z","tags":["naming"],"category":"General"},"headers":[],"relativePath":"adrs/1146361044/README.md","filePath":"adrs/1146361044/README.md"}'),s={name:"adrs/1146361044/README.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="helper-vs-util" tabindex="-1">Helper vs Util <a class="header-anchor" href="#helper-vs-util" aria-label="Permalink to &quot;Helper vs Util&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>At some point in your career you came across the debate of &quot;Utils&quot; vs &quot;Helpers&quot;.</p><p>Which one should you use in our code?</p><p>Giving the opportunity to bikeshedding, and/or creating diverging codebases across the organization.</p><p>We decided that across all the codebases we will be using <code>Helper</code>, regardless of the programming language or ecosystem.</p><p>There is no right or wrong answer here, just a matter of preferences and stick to a single way because it doesn&#39;t really matter which one you use except that it will matter for some at some point in their life, and it is not worth the debate in the long-term.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> use <code>Helpers</code> over <code>Util</code> across all the codebases.</li><li>You <strong>MUST</strong> use the plural <code>Helpers</code> as the preferred naming convention.</li></ul>',9)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
